'kb.added.unchanged':['The text is identical to the stored document; nothing changed.','Metin saklanan belgeyle aynı; hiçbir şey değişmedi.'],
'kb.removed':['Document removed.','Belge kaldırıldı.'],
'kb.search.title':['Search with citations','Alıntılı arama'],
'kb.search.label':['What are you looking for?','Ne arıyorsunuz?'],
